     1	package sk.knizat.tennisclub.config;
     2	
     3	import com.nimbusds.jose.jwk.source.ImmutableSecret;
     4	import lombok.RequiredArgsConstructor;
     5	import org.springframework.context.annotation.Bean;
     6	import org.springframework.context.annotation.Configuration;
     7	import org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;
     8	import org.springframework.security.oauth2.jose.jws.MacAlgorithm;
     9	import org.springframework.security.oauth2.jwt.JwtDecoder;
    10	import org.springframework.security.oauth2.jwt.JwtEncoder;
    11	import org.springframework.security.oauth2.jwt.JwtIssuerValidator;
    12	import org.springframework.security.oauth2.jwt.JwtTimestampValidator;
    13	import org.springframework.security.oauth2.jwt.NimbusJwtDecoder;
    14	import org.springframework.security.oauth2.jwt.NimbusJwtEncoder;
    15	import sk.knizat.tennisclub.security.JwtTokenService;
    16	
    17	import javax.crypto.SecretKey;
    18	import javax.crypto.spec.SecretKeySpec;
    19	import java.nio.charset.StandardCharsets;
    20	import java.time.Clock;
    21	import java.time.Duration;
    22	
    23	/**
    24	 * Nimbus JWT encoder/decoder over the shared HS256 secret ({@code app.security.jwt.secret}).
    25	 * <p>
    26	 * The decoder is shared by the resource server (bearer access tokens) and {@link JwtTokenService} (refresh
    27	 * tokens). Expiry is validated with a {@link JwtTimestampValidator} driven by the application {@link Clock}
    28	 * and no clock skew, because the same application issues and validates the tokens; this also lets tests move
    29	 * a controllable clock past the validity to observe expiry.
    30	 */
    31	@Configuration
    32	@RequiredArgsConstructor
    33	public class JwtConfig {
    34	
    35	    private static final String HMAC_ALGORITHM = "HmacSHA256";
    36	
    37	    private final AppProperties properties;
    38	    private final Clock clock;
    39	
    40	    @Bean
    41	    public JwtEncoder jwtEncoder() {
    42	        return new NimbusJwtEncoder(new ImmutableSecret<>(secretKey()));
    43	    }
    44	
    45	    @Bean
    46	    public JwtDecoder jwtDecoder() {
    47	        NimbusJwtDecoder decoder = NimbusJwtDecoder.withSecretKey(secretKey())
    48	                .macAlgorithm(MacAlgorithm.HS256)
    49	                .build();
    50	        JwtTimestampValidator timestampValidator = new JwtTimestampValidator(Duration.ZERO);
    51	        timestampValidator.setClock(clock);
    52	        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(
    53	                timestampValidator, new JwtIssuerValidator(JwtTokenService.ISSUER)));
    54	        return decoder;
    55	    }
    56	
    57	    private SecretKey secretKey() {
    58	        return new SecretKeySpec(properties.security().jwt().secret().getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM);
    59	    }
    60	}
