    24	                .info(new Info()
    25	                        .title("Tennis Club Reservations API")
    26	                        .version("v1")
    27	                        .description("Surface types, courts, reservations and user accounts of a tennis club. "
    28	                                + "Log in with HTTP Basic (phone number + password) on POST /api/auth/login and "
    29	                                + "use the returned access token as a bearer token everywhere else."))
    30	                .components(new Components()
    31	                        .addSecuritySchemes(BEARER_AUTH, new SecurityScheme()
    32	                                .type(SecurityScheme.Type.HTTP)
    33	                                .scheme("bearer")
    34	                                .bearerFormat("JWT"))
    35	                        .addSecuritySchemes(BASIC_AUTH, new SecurityScheme()
    36	                                .type(SecurityScheme.Type.HTTP)
    37	                                .scheme("basic")))
    38	                .addSecurityItem(new SecurityRequirement().addList(BEARER_AUTH));
    39	    }
