     3	import lombok.RequiredArgsConstructor;
     4	import lombok.extern.slf4j.Slf4j;
     5	import org.springframework.boot.ApplicationArguments;
     6	import org.springframework.boot.ApplicationRunner;
     7	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
     8	import org.springframework.stereotype.Component;
     9	import sk.knizat.tennisclub.dto.RoleDto;
    10	import sk.knizat.tennisclub.service.UserService;
    11	
    12	/**
    13	 * Bootstraps the first ADMIN account from {@code app.security.admin.*} (ARCHITECTURE.md O-3) when
    14	 * {@code app.security.admin.enabled=true}; independent of {@code app.data-init}. The account is created only
    15	 * when no non-deleted user with the configured phone number exists, so restarts are safe.
    16	 */
    17	@Slf4j
    18	@Component
    19	@ConditionalOnProperty(prefix = "app.security.admin", name = "enabled", havingValue = "true")
    20	@RequiredArgsConstructor
    21	public class AdminInitializer implements ApplicationRunner {
    22	
    23	    private final AppProperties properties;
    24	    private final UserService userService;
    25	
    26	    @Override
    27	    public void run(ApplicationArguments args) {
    28	        AppProperties.Security.Admin admin = properties.security().admin();
    29	        if (userService.findAuthUserByPhoneNumber(admin.phoneNumber()).isPresent()) {
    30	            log.info("Bootstrap admin account {} already exists", admin.phoneNumber());
    31	            return;
    32	        }
    33	        userService.createAccount(admin.phoneNumber(), admin.name(), admin.password(), RoleDto.ADMIN);
    34	        log.info("Bootstrap admin account {} ({}) created", admin.phoneNumber(), admin.name());
    35	    }
    36	}
