    29	    }
    30	
    31	    public RoleDto getRole() {
    32	        return user.role();
    33	    }
    34	
    35	    @Override
    36	    public Collection<? extends GrantedAuthority> getAuthorities() {
    37	        return List.of(new SimpleGrantedAuthority(ROLE_PREFIX + user.role().name()));
    38	    }
    39	
    40	    @Override
    41	    public String getPassword() {
