     1	package sk.knizat.tennisclub.security;
     2	
     3	import lombok.RequiredArgsConstructor;
     4	import org.springframework.security.oauth2.jose.jws.MacAlgorithm;
     5	import org.springframework.security.oauth2.jwt.JwsHeader;
     6	import org.springframework.security.oauth2.jwt.Jwt;
     7	import org.springframework.security.oauth2.jwt.JwtClaimsSet;
     8	import org.springframework.security.oauth2.jwt.JwtDecoder;
     9	import org.springframework.security.oauth2.jwt.JwtEncoder;
    10	import org.springframework.security.oauth2.jwt.JwtEncoderParameters;
    11	import org.springframework.security.oauth2.jwt.JwtException;
    12	import org.springframework.stereotype.Component;
    13	import sk.knizat.tennisclub.config.AppProperties;
    14	import sk.knizat.tennisclub.exception.UnauthorizedException;
    15	
    16	import java.time.Clock;
    17	import java.time.Instant;
    18	
    19	/**
    20	 * Issues and validates the application's HS256 tokens (ARCHITECTURE.md O-11).
    21	 * <p>
    22	 * Claims: {@code iss} = {@value #ISSUER}, {@code sub} = phone number, {@code role}, {@code type}
    23	 * ({@value #TYPE_ACCESS} or {@value #TYPE_REFRESH}), {@code iat} and {@code exp} computed from the application
    24	 * {@link Clock} and the configured validity. The decoder (see {@code config.JwtConfig}) verifies the signature,
    25	 * the issuer and the expiry against the same clock; this class additionally checks the token type.
    26	 */
    27	@Component
    28	@RequiredArgsConstructor
    29	public class JwtTokenService {
    30	
    31	    public static final String ISSUER = "tennis-club";
    32	    public static final String CLAIM_ROLE = "role";
    33	    public static final String CLAIM_TYPE = "type";
    34	    public static final String TYPE_ACCESS = "access";
    35	    public static final String TYPE_REFRESH = "refresh";
    36	
    37	    private final JwtEncoder encoder;
    38	    private final JwtDecoder decoder;
    39	    private final Clock clock;
    40	    private final AppProperties properties;
    41	
    42	    /** Issues a fresh access/refresh pair for the user, both starting now. */
    43	    public TokenPair issue(AppUserDetails user) {
    44	        Instant now = clock.instant();
    45	        Instant accessExpiry = now.plus(properties.security().jwt().accessTokenValidity());
    46	        Instant refreshExpiry = now.plus(properties.security().jwt().refreshTokenValidity());
    47	        return new TokenPair(
    48	                encode(user, TYPE_ACCESS, now, accessExpiry),
    49	                encode(user, TYPE_REFRESH, now, refreshExpiry),
    50	                accessExpiry,
    51	                refreshExpiry);
    52	    }
    53	
    54	    /**
    55	     * Decodes and validates a refresh token.
    56	     *
    57	     * @throws UnauthorizedException when the token is malformed, has a bad signature, is expired, or is not a
    58	     *                               refresh token
    59	     */
    60	    public Jwt decodeRefreshToken(String token) {
    61	        Jwt jwt;
    62	        try {
    63	            jwt = decoder.decode(token);
    64	        } catch (JwtException ex) {
    65	            throw new UnauthorizedException("Refresh token is invalid or expired");
    66	        }
    67	        if (!TYPE_REFRESH.equals(jwt.getClaimAsString(CLAIM_TYPE))) {
    68	            throw new UnauthorizedException("Token is not a refresh token");
    69	        }
    70	        return jwt;
    71	    }
    72	
    73	    private String encode(AppUserDetails user, String type, Instant issuedAt, Instant expiresAt) {
    74	        JwtClaimsSet claims = JwtClaimsSet.builder()
    75	                .issuer(ISSUER)
    76	                .subject(user.getUsername())
    77	                .claim(CLAIM_ROLE, user.getRole().name())
    78	                .claim(CLAIM_TYPE, type)
    79	                .issuedAt(issuedAt)
    80	                .expiresAt(expiresAt)
    81	                .build();
    82	        JwsHeader header = JwsHeader.with(MacAlgorithm.HS256).build();
    83	        return encoder.encode(JwtEncoderParameters.from(header, claims)).getTokenValue();
    84	    }
    85	}
