    19	    static void write(ObjectMapper objectMapper, HttpServletRequest request, HttpServletResponse response,
    20	                      HttpStatus status, String title, String detail) throws IOException {
    21	        ProblemDetail problem = ProblemDetail.forStatusAndDetail(status, detail);
