    28	    private final UserDao userDao;
    29	    private final UserMapper mapper;
    30	    private final PasswordEncoder passwordEncoder;
    31	    /** Used by the update/delete operations added in step 8 (soft delete timestamp). */
    32	    private final Clock clock;
    33	
    34	    @Override
    35	    @Transactional(readOnly = true)
    36	    public Optional<AuthUser> findAuthUserByPhoneNumber(String phoneNumber) {
    37	        String normalised;
    38	        try {
    39	            normalised = PhoneNumbers.normalise(phoneNumber);
    40	        } catch (ValidationException ex) {
    41	            // a login name that is not a phone number simply matches no account
    42	            return Optional.empty();
    43	        }
    44	        return userDao.findByPhoneNumber(normalised).map(mapper::toAuthUser);
    45	    }
    46	
    47	    @Override
    48	    @Transactional(readOnly = true)
    49	    public UserResponse findByPhoneNumber(String phoneNumber) {
    50	        String normalised = PhoneNumbers.normalise(phoneNumber);
    51	        return userDao.findByPhoneNumber(normalised)
    52	                .map(mapper::toResponse)
    53	                .orElseThrow(() -> new NotFoundException("User with phone number " + normalised + " not found"));
    54	    }
    55	
    56	    @Override
    57	    public UserResponse createAccount(String phoneNumber, String name, String rawPassword, RoleDto role) {
    58	        String normalised = PhoneNumbers.normalise(phoneNumber);
    59	        if (rawPassword == null || rawPassword.isBlank()) {
    60	            throw new ValidationException("password must not be blank");
    61	        }
    62	        if (userDao.findByPhoneNumber(normalised).isPresent()) {
    63	            throw duplicatePhone(normalised);
    64	        }
    65	        User user = new User();
    66	        user.setPhoneNumber(normalised);
    67	        user.setName(name.trim());
    68	        user.setPasswordHash(passwordEncoder.encode(rawPassword));
    69	        user.setRole(mapper.toEntity(role));
    70	        return mapper.toResponse(UniqueKeys.saveOrConflict(() -> userDao.save(user),
    71	                duplicatePhone(normalised).getMessage()));
    72	    }
